    this.addCommand({ id: "dream-now", name: t("Dreaming\uFF1A\u6574\u7406 AI \u8BB0\u5F55\u4E0E\u7528\u6237\u65E5\u5FD7\u4E3A\u957F\u671F\u8BB0\u5FC6"), callback: () => this.dreaming.run(true, { drain: true }) });
